void GRPC_TO_TURBOLINK(const ::nightfall::v1::SkillCatalogEntry* in, FGrpcNightfallV1SkillCatalogEntry* out)
{
    out->SkillId=in->skill_id();
    out->Key=StringCast<TCHAR>((const UTF8CHAR*)(in->key().c_str())).Get();
    out->DisplayName=StringCast<TCHAR>((const UTF8CHAR*)(in->display_name().c_str())).Get();
    out->MaxLevel=in->max_level();
    out->EffectImplemented=in->effect_implemented();
    out->DeferredReasons.Empty();
    for (int i=0; i<in->deferred_reasons_size(); ++i) {
        out->DeferredReasons.Add(StringCast<TCHAR>((const UTF8CHAR*)(in->deferred_reasons(i).c_str())).Get());
    }
    out->L2Ref=StringCast<TCHAR>((const UTF8CHAR*)(in->l2_ref().c_str())).Get();
    out->MpConsumeStart.Empty();
    for (int i=0; i<in->mp_consume_start_size(); ++i) {
        out->MpConsumeStart.Add(in->mp_consume_start(i));
    }
    out->MpConsumeEnd.Empty();
    for (int i=0; i<in->mp_consume_end_size(); ++i) {
        out->MpConsumeEnd.Add(in->mp_consume_end(i));
    }
    out->HpConsume.Empty();
    for (int i=0; i<in->hp_consume_size(); ++i) {
        out->HpConsume.Add(in->hp_consume(i));
    }
    out->ReuseMs.Empty();
    for (int i=0; i<in->reuse_ms_size(); ++i) {
        out->ReuseMs.Add(in->reuse_ms(i));
    }
    out->HitTimeMs.Empty();
    for (int i=0; i<in->hit_time_ms_size(); ++i) {
        out->HitTimeMs.Add(in->hit_time_ms(i));
    }
    out->OperateType=[](int value) { switch (value) { case 0: case 1: case 2: case 3: case 4: case 5: case 6: return StaticCast<EGrpcNightfallV1SkillOperateType>(value); default: return EGrpcNightfallV1SkillOperateType::SKILL_OPERATE_TYPE_UNSPECIFIED; } }(static_cast<int>(in->operate_type()));
    out->TargetType.Empty();
    for (int i=0; i<in->target_type_size(); ++i) {
        out->TargetType.Add(StringCast<TCHAR>((const UTF8CHAR*)(in->target_type(i).c_str())).Get());
    }
    out->AffectScope.Empty();
    for (int i=0; i<in->affect_scope_size(); ++i) {
        out->AffectScope.Add(StringCast<TCHAR>((const UTF8CHAR*)(in->affect_scope(i).c_str())).Get());
    }
}

void TURBOLINK_TO_GRPC(const FGrpcNightfallV1SkillCatalogEntry* in, ::nightfall::v1::SkillCatalogEntry* out)
{
    out->set_skill_id(in->SkillId);
    out->set_key((const char*)StringCast<UTF8CHAR>(*(in->Key)).Get());
    out->set_display_name((const char*)StringCast<UTF8CHAR>(*(in->DisplayName)).Get());
    out->set_max_level(in->MaxLevel);
    out->set_effect_implemented(in->EffectImplemented);
    for(const auto& value : in->DeferredReasons) {
        out->add_deferred_reasons((const char*)StringCast<UTF8CHAR>(*(value)).Get());
    }
    out->set_l2_ref((const char*)StringCast<UTF8CHAR>(*(in->L2Ref)).Get());
    for(const auto& value : in->MpConsumeStart) {
        out->add_mp_consume_start(value);
    }
    for(const auto& value : in->MpConsumeEnd) {
        out->add_mp_consume_end(value);
    }
    for(const auto& value : in->HpConsume) {
        out->add_hp_consume(value);
    }
    for(const auto& value : in->ReuseMs) {
        out->add_reuse_ms(value);
    }
    for(const auto& value : in->HitTimeMs) {
        out->add_hit_time_ms(value);
    }
    out->set_operate_type(::nightfall::v1::SkillOperateType(static_cast<uint8>(in->OperateType)));
    for(const auto& value : in->TargetType) {
        out->add_target_type((const char*)StringCast<UTF8CHAR>(*(value)).Get());
    }
    for(const auto& value : in->AffectScope) {
        out->add_affect_scope((const char*)StringCast<UTF8CHAR>(*(value)).Get());
    }
}

